  throw new Error(
    'No usable series IDs in Settings. Expected a comma separated list like ' +
    '"UNRATE, CPIAUCSL, DGS10". Find IDs at fred.stlouisfed.org.'
  );
}

// Deduplicated, because the Data Table is keyed on the series ID and the same
// one listed twice would race itself on the upsert.
return [...new Set(ids)].map((series_id) => ({ json: { series_id } }));

