// collapse. frequency_short is D, W, M or Q.
const asked = $('Pick The Indicators').all().map((i) => i.json.series_id);
const items = $input.all();

return asked.map((series_id, i) => {
  const got = payloadOf(items[i]);
  const d = got.data || {};
  return {
    json: {
      series_id,
      title: d.title || series_id,
      units: d.units || '',
      units_short: d.units_short || '',
      frequency: String(d.frequency_short || 'M').toUpperCase(),
      seasonal: d.seasonal_adjustment_short || '',
      last_updated: d.last_updated || null,
      info_error: got.error || got.note || null,
    },
  };
});

