  } catch (e) {
    return { note: text.replace(/\s+/g, ' ').trim().slice(0, 200) };
  }
}

// FRED writes an observation it has not published as the string ".". Number('.')
// is NaN and Number('') is 0, and either one reaching a comparison makes a trend
// test quietly wrong rather than loudly broken.
function num(value) {
  if (value === null || value === undefined || value === '' || value === '.') return null;
  const n = Number(value);
  return Number.isFinite(n) ? n : null;
}

// Newest first, and every value coerced here rather than at the point of
// comparison. A "." left as a string sorts and compares without complaint.
const asked = $('Pick The Indicators').all().map((i) => i.json.series_id);
const items = $input.all();

return asked.map((series_id, i) => {
  const got = payloadOf(items[i]);

  if (got.error || got.note) {
    return {
      json: {
        series_id,
        values: [],
        history_error: got.error || got.note,
      },
    };
  }

  const d = got.data || {};
  const raw = Array.isArray(d.observations) ? d.observations : [];
  const values = raw
    .map((o) => ({ date: String(o.date), value: num(o.value) }))
    .filter((o) => o.value !== null);

  return {
    json: {
      series_id,
      title: d.title || series_id,
      values,
      returned: raw.length,
      // Said out loud, because "2 of 300 observations were unpublished" and
      // "298 observations" are different facts and only one of them is visible
      // once the dots are gone.
      unpublished: raw.length - values.length,
      history_error: values.length < 4
        ? 'Only ' + values.length + ' usable observation(s) came back. A trend needs at least four.'
        : null,
    },
  };
});

// Everything the brief says about a single series is decided here, and none of
// it is a level. A level is published everywhere; the shape is what nobody
// writes down.
const cfg = $('Settings').first().json;
const zBand = Math.max(0.5, Number(cfg.z_threshold) || 1.5);

// How many observations back a month, a quarter and a year are. The observations
// call cannot tell you this - it answers "native" for everything - so it comes
// from get_series_info. A daily series is trading days, not calendar days.
const STEPS = {
  D: { month: 21, quarter: 63, year: 252 },
  W: { month: 4, quarter: 13, year: 52 },
  M: { month: 1, quarter: 3, year: 12 },
  Q: { month: 1, quarter: 1, year: 4 },
};

const info = new Map($('Read The Series Description').all().map((i) => [i.json.series_id, i.json]));

// Both lanes are read by name rather than off the input. The merge above is a
// barrier, not a join: it appends, so $input here is the eight description rows
// followed by the eight history rows, and scoring that gives sixteen items -
// eight of them a description with no observations, scored as "no data" and
// saved to the table as such. Every node stays green while the watchlist
// silently doubles.
const history = $('Read The History').all().map((i) => i.json);

function pct(now, then) {
  if (now === null || then === null || then === 0) return null;
  return Math.round(((now - then) / Math.abs(then)) * 1000) / 10;
}

return history.map((h) => {
  const meta = info.get(h.series_id) || {};
  const values = h.values || [];

  if (h.history_error || values.length < 4) {
    return {
      json: {
        series_id: h.series_id,
        title: meta.title || h.series_id,
        usable: false,
        reason: h.history_error || 'not enough history',
        regime: 'no data',
      },
    };
  }

  const step = STEPS[meta.frequency] || STEPS.M;
  const at = (n) => (values[n] ? values[n].value : null);
  const latest = at(0);

  // Consecutive moves in the same direction, newest first. A flat print ends
  // the streak rather than extending it - three rises then a flat month is not
  // a four-month trend, and calling it one is how a chart lies.
  let streak = 0;
  const dir = latest > at(1) ? 1 : latest < at(1) ? -1 : 0;
  if (dir !== 0) {
    for (let i = 0; i + 1 < values.length; i += 1) {
      const d = values[i].value > values[i + 1].value ? 1 : values[i].value < values[i + 1].value ? -1 : 0;
      if (d !== dir) break;
      streak += 1;
    }
  }

  // Against the last year of its own history rather than a fixed band, because
  // a 0.2 move is nothing on the unemployment rate and a lot on the fed funds
  // rate. Population standard deviation: this is the whole window, not a sample
  // drawn from it.
  const window = values.slice(0, step.year).map((v) => v.value);
  const mean = window.reduce((a, b) => a + b, 0) / window.length;
  const variance = window.reduce((a, b) => a + (b - mean) * (b - mean), 0) / window.length;
  const sd = Math.sqrt(variance);
  const z = sd > 0 ? Math.round(((latest - mean) / sd) * 100) / 100 : 0;

  const quarterMove = pct(latest, at(step.quarter));
  const yearMove = pct(latest, at(step.year));

  // Five bands rather than up/down, because "rising" and "rising faster than it
  // has all year" are the two different messages this is for.
  let regime = 'steady';
  if (z >= zBand) regime = 'stretched high';
  else if (z <= -zBand) regime = 'stretched low';
  else if (quarterMove !== null && quarterMove > 0 && streak >= 3) regime = 'rising';
  else if (quarterMove !== null && quarterMove < 0 && streak >= 3) regime = 'falling';

  return {
    json: {
      series_id: h.series_id,
      title: meta.title || h.series_id,
      units: meta.units_short || meta.units || '',
      frequency: meta.frequency || 'M',
      usable: true,
      as_of: values[0].date,
      value: latest,
      previous: at(1),
      month_move_pct: pct(latest, at(step.month)),
      quarter_move_pct: quarterMove,
      year_move_pct: yearMove,
      streak: streak,
      streak_direction: dir > 0 ? 'up' : dir < 0 ? 'down' : 'flat',
      z_score: z,
      year_low: Math.min(...window),
      year_high: Math.max(...window),
      unpublished: h.unpublished || 0,
      regime: regime,
      derived: false,
    },
  };
});

// The three signals worth having are not series, and none of them can be
// fetched: each needs two series held at the same time. This is the node that
// justifies pulling the whole set in one run rather than alerting per series.
const cfg = $('Settings').first().json;
const rows = $input.all().map((i) => i.json);
const by = new Map(rows.filter((r) => r.usable).map((r) => [r.series_id, r]));
const out = rows.slice();

function add(row) {
  out.push({ ...row, usable: true, derived: true, frequency: 'M', unpublished: 0 });
}

// 1. The yield curve. Inverted means the 2-year pays more than the 10-year, and
//    the sign is the whole signal - the magnitude is commentary.
const ten = by.get('DGS10');
const two = by.get('DGS2');
if (ten && two) {
  const spread = Math.round((ten.value - two.value) * 100) / 100;
  add({
    series_id: 'DERIVED_CURVE',
    title: '10-year minus 2-year Treasury spread',
    units: '%',
    as_of: ten.as_of,
    value: spread,
    regime: spread < 0 ? 'inverted' : spread < 0.25 ? 'flat' : 'normal',
    note:
      'The 10-year is at ' + ten.value + '% and the 2-year at ' + two.value + '%. ' +
      (spread < 0
        ? 'An inverted curve means the market is paid more to lend for two years than for ten.'
        : 'A positive spread is the ordinary shape.'),
  });
}

// 2. The Sahm rule: the three-month average unemployment rate against its lowest
//    three-month average of the previous year. Half a point above it has marked
//    the start of every post-war US recession. It needs the raw history, not the
//    scored row, so it reads the series back by name.
const unrateHistory = $('Read The History').all().map((i) => i.json).find((h) => h.series_id === 'UNRATE');
if (unrateHistory && (unrateHistory.values || []).length >= 15) {
  const v = unrateHistory.values.map((o) => o.value);
  const avg3 = (start) => (v[start] + v[start + 1] + v[start + 2]) / 3;
  const current = avg3(0);
  let low = Infinity;
  for (let i = 1; i <= 12; i += 1) low = Math.min(low, avg3(i));
  const gap = Math.round((current - low) * 100) / 100;
  add({
    series_id: 'DERIVED_SAHM',
    title: 'Sahm rule gap (3-month unemployment average above its 12-month low)',
    units: 'pp',
    as_of: unrateHistory.values[0].date,
    value: gap,
    regime: gap >= 0.5 ? 'triggered' : gap >= 0.3 ? 'approaching' : 'clear',
    note:
      'The three-month average is ' + Math.round(current * 100) / 100 + '% against a ' +
      'twelve-month low of ' + Math.round(low * 100) / 100 + '%. Half a point is the trigger.',
  });
}

// 3. The policy rate net of inflation. A nominal rate says nothing on its own:
//    4% with 2% inflation and 4% with 6% inflation are opposite policies.
const funds = by.get('FEDFUNDS');
const cpiHistory = $('Read The History').all().map((i) => i.json).find((h) => h.series_id === 'CPIAUCSL');
if (funds && cpiHistory && (cpiHistory.values || []).length >= 13) {
  const cv = cpiHistory.values;
  const inflation = ((cv[0].value - cv[12].value) / cv[12].value) * 100;
  const real = Math.round((funds.value - inflation) * 100) / 100;
  add({
    series_id: 'DERIVED_REALRATE',
    title: 'Fed funds rate net of CPI inflation',
    units: '%',
    as_of: funds.as_of,
    value: real,
    regime: real > 1 ? 'restrictive' : real < 0 ? 'accommodative' : 'neutral',
    note:
      'The fed funds rate is ' + funds.value + '% and CPI is up ' +
      Math.round(inflation * 10) / 10 + '% over the year.',
  });
}

// Never empty. A run where every series failed still has to reach the IF, or
// the "nothing shifted" branch is the one branch that never fires.
if (!out.length) {
  return [{ json: { series_id: 'NONE', usable: false, regime: 'no data', reason: 'No series returned data.' } }];
}
return out.map((json) => ({ json }));

// The regime label is the memory. A level moving is not news - FRED publishes
// levels - and the shape of a series only becomes visible once you have last
// week's reading of it to hold the new one against.
const last = new Map(
  $('Read Last Week\'s Reading').all()
    .filter((i) => i.json && i.json.series_id)
    .map((i) => [String(i.json.series_id), i.json])
);

return $input.all().map((item) => {
  const r = item.json;
  const prior = last.get(r.series_id);
  const priorRegime = prior ? String(prior.regime || '') : '';

  // First run: everything is new and nothing has shifted. Reporting the whole
  // watchlist as a change on day one would train the reader to ignore it.
  const firstSighting = !prior;
  const shifted = !firstSighting && priorRegime !== '' && priorRegime !== r.regime;

  return {
    json: {
      ...r,
      previous_regime: priorRegime || null,
      previous_value: prior ? Number(prior.value) : null,
      previous_seen_on: prior ? prior.seen_on : null,
      first_sighting: firstSighting,
      shifted: !!(r.usable && shifted),
    },
  };
});

