// One message for the whole watchlist, not one per series. The IF above has
// narrowed this branch to the weeks where something moved, and the full picture
// is read back by name.
const rows = $('Compare With Last Week').all().map((i) => i.json);
const shifted = rows.filter((r) => r.shifted);
const usable = rows.filter((r) => r.usable);
const broken = rows.filter((r) => !r.usable);
// A single-item input by construction: the chain above runs executeOnce, so it
// answers with one paragraph for the whole watchlist rather than one per series.
const reading = String(($input.first().json || {}).text || '').trim();

// FRED titles are catalogue entries, not labels: DGS10 is "Market Yield on U.S.
// Treasury Securities at 10-Year Constant Maturity, Quoted on an Investment
// Basis". Printed whole they push the number off the end of a Slack line. The
// qualifying clause after the first comma is the part nobody needs.
const label = (r) => {
  const t = String(r.title || r.series_id);
  const head = t.split(',')[0];
  // Only when the head still names the series on its own. PAYEMS is "All
  // Employees, Total Nonfarm", and "All Employees" of what is not a label.
  if (head.length >= 20 && head.length <= 62) return head;
  return t.length > 62 ? t.slice(0, 59).trimEnd() + '...' : t;
};

// "4.1 %" reads like a typo and "206000 Number" reads like a bug. A unit that is
// a symbol joins the number, a unit that is a word follows a space, and FRED's
// placeholder unit for a plain count is dropped.
const withUnits = (r) => {
  const u = String(r.units || '').trim();
  if (!u || u.toLowerCase() === 'number') return String(r.value);
  return /^[%°]/.test(u) || u === 'pp' ? r.value + u : r.value + ' ' + u;
};

const arrow = (r) => {
  if (r.quarter_move_pct === null || r.quarter_move_pct === undefined) return '';
  const s = r.quarter_move_pct > 0 ? '+' : '';
  return '  (' + s + r.quarter_move_pct + '% over the quarter)';
};

const lines = [];
lines.push('*Macro regime check* - ' + new Date().toISOString().slice(0, 10));
lines.push('');
lines.push(reading || '_no reading was returned this week_');
lines.push('');
lines.push('*Changed regime*');
shifted.forEach((r) => {
  lines.push(
    '- *' + label(r) + '*: ' + withUnits(r) +
    ' - ' + (r.previous_regime || 'unknown') + ' to *' + r.regime + '*' + arrow(r)
  );
  if (r.note) lines.push('    ' + r.note);
  if (r.streak >= 3) {
    lines.push('    ' + r.streak + ' consecutive moves ' + r.streak_direction + '.');
  }
});

lines.push('');
lines.push('*Unchanged* - ' + usable.filter((r) => !r.shifted).length + ' of ' + usable.length + ' series');
usable
  .filter((r) => !r.shifted)
  .forEach((r) => {
    lines.push('- ' + label(r) + ': ' + withUnits(r) + ' (' + r.regime + ')');
  });

// A series that failed is reported, not dropped. A watchlist that quietly
// shrinks reads as a calm week.
if (broken.length) {
  lines.push('');
  lines.push('*Not read this week*');
  broken.forEach((r) => lines.push('- ' + r.series_id + ': ' + (r.reason || 'no data')));
}

const holidays = usable.reduce((a, r) => a + (r.unpublished || 0), 0);
if (holidays) {
  lines.push('');
  lines.push('_' + holidays + ' observation(s) were unpublished and skipped._');
}

return [{ json: { message: lines.join('\n'), shifted: shifted.length } }];
